begin;
create extension if not exists pgtap with schema extensions;
select plan(32);
insert into auth.users(id,aud,role,email,created_at,updated_at) values('16200000-0000-4000-8000-000000000010','authenticated','authenticated','add-student-manager@example.test',now(),now());
insert into public.profiles(id,role,full_name,is_active) values('16200000-0000-4000-8000-000000000010','academic_manager','TEST-ENROLL-MANAGER',true);
insert into public.b2c_classes(id,program_slug,name,capacity,enrolled_count) values
('16200000-0000-4000-8000-000000000001','tieng-anh','TEST-ENROLL-CLASS',2,0),
('16200000-0000-4000-8000-000000000002','tieng-trung','TEST-ENROLL-OTHER',3,0),
('16200000-0000-4000-8000-000000000003','tieng-anh','TEST-ENROLL-CLOSED',3,0);
update public.b2c_classes set status='completed' where id='16200000-0000-4000-8000-000000000003';
insert into public.b2c_students(id,source_key,full_name,phone,guardian_name) values('16200000-0000-4000-8000-000000000020','test-enroll-existing','TEST-ENROLL-EXISTING','0901234567','TEST-GUARDIAN');
select ok((select relrowsecurity from pg_class where oid='public.b2c_enrollment_requests'::regclass),'Request ledger RLS enabled');
select ok(not has_function_privilege('anon','public.add_b2c_class_student(jsonb)','EXECUTE'),'Anonymous cannot invoke enrollment RPC');
select set_config('request.jwt.claims','{"sub":"16200000-0000-4000-8000-000000000010","role":"authenticated"}',true);
set local role authenticated;
select set_config('test.enroll_payload','{"request_id":"16200000-0000-4000-8000-000000000030","class_id":"16200000-0000-4000-8000-000000000001","mode":"new","student_id":"","full_name":"TEST-ENROLL-NEW","phone":"0901111222","guardian_name":"TEST-PARENT","date_of_birth":"2016-03-01","customer_source":"referral","referrer_name":"TEST-REFERRER","salesperson":"TEST-SALES","enrollment_date":"2026-10-16","learning_start_date":"2026-10-16","tuition_end_date":"2027-01-16","learning_goal":"certificate","certificate_goal":"HSK1","notes":"TEST-NOTE"}',true);
select lives_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb)$$,'Academic manager creates student and enrollment');
select is((select count(*)::integer from public.b2c_students where source_key='manual:16200000-0000-4000-8000-000000000030'),1,'One new student profile');
select ok((select code~'^B2C-HV[0-9]{6,}$' from public.b2c_students where source_key='manual:16200000-0000-4000-8000-000000000030'),'Student code generated');
select is((select enrolled_count from public.b2c_classes where id='16200000-0000-4000-8000-000000000001'),1,'Class count updated');
select lives_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb)$$,'Exact request retry succeeds');
select is((select count(*)::integer from public.b2c_enrollments where source_key='manual:16200000-0000-4000-8000-000000000030'),1,'Retry never duplicates enrollment');
select throws_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb||'{"full_name":"DIFFERENT"}')$$,'22023',null,'Changed retry rejected');
select is((public.find_b2c_enrollment_students('16200000-0000-4000-8000-000000000001','TEST-ENROLL',0)->>'total')::integer,1,'Picker excludes enrolled student');
select is((public.find_b2c_enrollment_students('16200000-0000-4000-8000-000000000001','TEST-GUARDIAN',0)->>'total')::integer,1,'Picker searches guardian');
select is((public.find_b2c_enrollment_students('16200000-0000-4000-8000-000000000001','%',0)->>'total')::integer,0,'Search percent is literal');
select lives_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb||'{"request_id":"16200000-0000-4000-8000-000000000031","mode":"existing","student_id":"16200000-0000-4000-8000-000000000020","full_name":"MUST NOT REWRITE"}')$$,'Existing student enrolled');
select is((select full_name from public.b2c_students where id='16200000-0000-4000-8000-000000000020'),'TEST-ENROLL-EXISTING','Existing profile untouched');
select throws_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb||'{"request_id":"16200000-0000-4000-8000-000000000032","mode":"existing","student_id":"16200000-0000-4000-8000-000000000020"}')$$,'22023',null,'Duplicate class/student blocked');
select throws_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb||'{"request_id":"16200000-0000-4000-8000-000000000033"}')$$,'22023',null,'Full class blocked');
select is((select count(*)::integer from public.b2c_students where source_key='manual:16200000-0000-4000-8000-000000000033'),0,'Full class creates no orphan profile');
select lives_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb||'{"request_id":"16200000-0000-4000-8000-000000000034","class_id":"16200000-0000-4000-8000-000000000002","mode":"existing","student_id":"16200000-0000-4000-8000-000000000020"}')$$,'Same student may join a different class');
select is((select count(*)::integer from public.b2c_enrollments where student_id='16200000-0000-4000-8000-000000000020'),2,'Two enrollments share one student');
select set_config('test.enroll_payload',(current_setting('test.enroll_payload')::jsonb||'{"request_id":"16200000-0000-4000-8000-000000000035","class_id":"16200000-0000-4000-8000-000000000002"}')::text,true);
select throws_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb||'{"class_id":"16200000-0000-4000-8000-000000000003"}')$$,'22023',null,'Closed class cannot enroll');
select throws_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb||'{"mode":"existing","student_id":"16200000-0000-4000-8000-000000000099"}')$$,'22023',null,'Missing student rejected');
select throws_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb||'{"phone":"123"}')$$,'22023',null,'Invalid contact rejected');
select throws_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb||'{"date_of_birth":"2099-01-01"}')$$,'22023',null,'Future birth date rejected');
select throws_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb||'{"tuition_end_date":"2026-01-01"}')$$,'22023',null,'Inconsistent learning dates rejected');
select throws_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb||'{"certificate_goal":""}')$$,'22023',null,'Certificate goal requires certificate');
select throws_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb||'{"referrer_name":""}')$$,'22023',null,'Referral requires referrer');
select throws_ok($$update public.b2c_enrollment_requests set payload='{}'$$,'42501',null,'Request ledger immutable to users');
select is((select count(*)::integer from public.b2c_tuition_packages where enrollment_id in (select id from public.b2c_enrollments where class_id in ('16200000-0000-4000-8000-000000000001','16200000-0000-4000-8000-000000000002'))),0,'Enrollment does not invent tuition packages');
reset role;
select is((select actor_id from public.b2c_change_history where enrollment_id=(select enrollment_id from public.b2c_enrollment_requests where request_id='16200000-0000-4000-8000-000000000030')),'16200000-0000-4000-8000-000000000010'::uuid,'Audit captures actual manager');
alter table public.b2c_change_history add constraint test_enroll_audit_failure check(entity_type<>'enrollment') not valid;
set local role authenticated;
select throws_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb)$$,'23514',null,'Audit failure rolls back entire enrollment');
select is((select count(*)::integer from public.b2c_students where source_key='manual:16200000-0000-4000-8000-000000000035'),0,'No orphan student after failed audit');
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok($$select public.add_b2c_class_student(current_setting('test.enroll_payload')::jsonb)$$,'42501',null,'Nonmanager blocked');
select * from finish();
rollback;
